function rollbackBudget(stages) {
  return stages.reduce(function (sum, s) { return sum + s.seconds; }, 0);
}

function verdict(total, sloSeconds) {
  return total <= sloSeconds ? 'WITHIN SLO' : 'OVER SLO';
}

// Phases of an automated metric-gated rollback, in seconds.
var withDrain = [
  { phase: 'detect (canary error-rate breach)', seconds: 60 },
  { phase: 'decide (auto-rollback trigger)', seconds: 10 },
  { phase: 'drain old/new connections (L7)', seconds: 20 },
  { phase: 'reschedule healthy pods', seconds: 30 }
];
var noDrain = [
  { phase: 'detect (canary error-rate breach)', seconds: 60 },
  { phase: 'decide (auto-rollback trigger)', seconds: 10 },
  { phase: 'sever in-flight + client retry storm (L4)', seconds: 120 },
  { phase: 'reschedule healthy pods', seconds: 30 }
];
var slo = 180;

var a = rollbackBudget(withDrain);
var b = rollbackBudget(noDrain);
console.log('L7 drain total: ' + a + 's -> ' + verdict(a, slo));
console.log('L4 no-drain total: ' + b + 's -> ' + verdict(b, slo));
console.log('Penalty of skipping drain: ' + (b - a) + 's');
